const sourceRoot=new URL('../../',import.meta.url);
const write=(root,relative,record)=>{const p=path.join(root,relative);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,Buffer.isBuffer(record)?record:JSON.stringify(record,null,2)+'\n');};
const stamp=(index,offset=0)=>'2026-10-08T01:'+String([0,10,31,40,45,50][index]+offset).padStart(2,'0')+':00Z';
const ctx=label=>'ctx-'+canonicalSha('TEST_ONLY '+label);
const crc=b=>{let n=0xffffffff;for(const v of b){n^=v;for(let j=0;j<8;j++)n=n&1?0xedb88320^(n>>>1):n>>>1;}return (n^0xffffffff)>>>0;};
